// No real server, user data, credentials or network: exercise the exact adapter
// generated by the pinned upstream CLI against a minimal OpenCode V1 host.
import assert from "node:assert/strict";
import { mkdirSync, readFileSync, readdirSync, statSync, symlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const data = process.env.AI_MEMORY_DATA_DIR;
const root = join(process.env.HOME, "opted-in");
const unmarked = join(process.env.HOME, "unmarked");
mkdirSync(join(root, "secrets"), { recursive: true });
mkdirSync(unmarked, { recursive: true });
writeFileSync(join(root, ".ai-memory.toml"), `workspace = "personal"
project = "fixture"
[capture]
ignore_paths = ["secrets/**"]
`);
writeFileSync(join(data, "sops-token"), "fixture-only-not-a-real-token\n", { mode: 0o400 });
symlinkSync(join(data, "sops-token"), join(data, "auth-token"));
let offline = true;
const delivered = [];
globalThis.fetch = async (input, options = {}) => {
  options.signal?.throwIfAborted();
  if (offline) throw new Error("simulated outage");
  const url = new URL(input);
  if (url.pathname === "/hook") {
    assert.equal(options.headers.Authorization, "Bearer fixture-only-not-a-real-token");
    delivered.push({ url, body: JSON.parse(options.body) });
  }
  return new Response("");
};
const { default: plugin } = await import(pathToFileURL(process.argv[2]).href);

async function host(directory) {
  const hooks = await plugin({ directory });
  return {
    prompt: (sessionID, messageID, text) => hooks["chat.message"](
      { sessionID, messageID }, { parts: [{ type: "text", text }] },
    ),
    tool: (sessionID, path) => hooks["tool.execute.after"](
      { sessionID, tool: "read", callID: "secret", args: { path } },
      { output: "MUST_NOT_BE_CAPTURED" },
    ),
    dispose: hooks.dispose,
  };
}
const spool = join(data, "hook-spool");
const pending = () => {
  try { return readdirSync(spool).filter((name) => name.endsWith(".json")); }
  catch { return []; }
};
async function until(predicate) {
  const deadline = performance.now() + 12000;
  while (!predicate()) {
    assert.ok(performance.now() < deadline, "recovery must finish within its test budget");
    await new Promise((resolve) => setTimeout(resolve, 20));
  }
}
// A real OpenCode host stays alive while the adapter's unref'd timers drain.
const alive = setInterval(() => {}, 1000);
try {
  const a = await host(root);
  const start = performance.now();
  await a.prompt("offline", "p1", "offline evidence");
  await a.tool("offline", join(root, "secrets", "test"));
  await a.dispose();
  assert.ok(performance.now() - start < 6000, "outage must not stall the host indefinitely");
  const files = pending();
  assert.ok(files.length > 0, "offline captures must be spooled");
  const entries = files.map((name) => {
    const file = join(spool, name);
    assert.equal(statSync(file).mode & 0o777, 0o600);
    return JSON.parse(readFileSync(file, "utf8"));
  });
  assert.equal(statSync(spool).mode & 0o777, 0o700);
  assert.ok(entries.some((entry) => entry.body.includes("offline evidence")));
  assert.ok(entries.some((entry) => new URL(entry.url).searchParams.get("event") === "session-end"),
    "V1 disposal must spool SessionEnd even during an outage");
  assert.ok(entries.every((entry) => !entry.body.includes("MUST_NOT_BE_CAPTURED")));
  const keys = entries.map((entry) => {
    const url = new URL(entry.url);
    assert.equal(url.searchParams.get("workspace"), "personal");
    assert.equal(url.searchParams.get("project"), "fixture");
    assert.ok(url.searchParams.get("ingest_key"));
    return url.searchParams.get("ingest_key");
  });

  offline = false;
  const b = await host(root);
  await b.prompt("reconnected", "p2", "online");
  await until(() => pending().length === 0);
  await b.dispose();
  assert.ok(delivered.some(({ url, body }) =>
    url.searchParams.get("event") === "session-end" && body.sessionID === "reconnected"),
    "V1 disposal must deliver SessionEnd for its tracked session");
  for (const key of keys) {
    assert.ok(delivered.some(({ url }) => url.searchParams.get("ingest_key") === key), "retry must preserve the ingest key");
  }

  const before = delivered.length;
  const c = await host(unmarked);
  await c.prompt("unmarked", "p3", "NOT_OPTED_IN");
  await c.dispose();
  assert.equal(delivered.length, before, "unmarked projects must not emit captures");
  assert.equal(pending().length, 0);
  console.log("PASS: V1 disposal, bounded outage, private spool, exclusions, stable-key recovery, allowlist");
} finally {
  clearInterval(alive);
}
